function validateChat(input) {
  const cfg = input.setup;
  if (!cfg || typeof cfg !== 'object') throw new Error('Open Skill Configuration and complete setup.');
  if (typeof cfg.model !== 'string' || !cfg.model.trim() || /[\r\n\u0000]/.test(cfg.model)) throw new Error('Set setup.model to a currently available OpenRouter tool-calling model.');
  if (!Array.isArray(cfg.repositories) || cfg.repositories.length < 1 || cfg.repositories.length > 3) throw new Error('Configure between 1 and 3 approved repositories.');
  const repos = cfg.repositories.map((r) => {
    if (!r || !/^[A-Za-z0-9][A-Za-z0-9-]{0,38}$/.test(r.owner || '') || !/^[A-Za-z0-9_.-]{1,100}$/.test(r.repo || '') || ['.', '..'].includes(r.repo)) throw new Error('Each approved repository needs a valid owner and repository name.');
    if (!/^[0-9a-f]{40}$/i.test(r.commit || '')) throw new Error('Pin each approved repository to its full 40-character commit SHA. Branch names are not accepted.');
    if (!Array.isArray(r.roots) || !r.roots.length || r.roots.length > 3) throw new Error('Give each repository 1 to 3 approved root paths. Use an empty string for its root.');
    const roots = [...new Set(r.roots.map((v) => {
      if (typeof v !== 'string' || v.length > 240 || /[%?#\\\u0000-\u001f\u007f]/.test(v) || v.startsWith('/') || v.endsWith('/') || v.split('/').some(s => s === '.' || s === '..' || (s === '' && v !== ''))) throw new Error('Approved roots must be clean repository-relative paths.');
      return v;
    }))];
    return { key: `${r.owner}/${r.repo}`, owner: r.owner, repo: r.repo, commit: r.commit.toLowerCase(), roots };
  });
  if (new Set(repos.map(r => r.key.toLowerCase())).size !== repos.length) throw new Error('Remove duplicate approved repositories.');
  const chatInput = typeof input.chatInput === 'string' ? input.chatInput.trim() : '';
  if (!chatInput || chatInput.length > 6000) throw new Error('Send a nonempty chat message of at most 6000 characters.');
  const sessionId = typeof input.sessionId === 'string' ? input.sessionId : '';
  if (!/^[A-Za-z0-9_:\-]{1,160}$/.test(sessionId)) throw new Error('A valid chat session ID is required. Use the connected n8n chat trigger.');
  return { chatInput, sessionId, model: cfg.model.trim(), repositories: repos, maxFileBytes: 20000, maxMarkdownFiles: 1500, maxTreeEntries: 15000, maxDirectoryEntries: 150 };
}
return [{json:validateChat($input.first().json)}];

function prepareIndex(responses, expanded, validated) {
  if (responses.length !== expanded.length) throw new Error('GitHub returned an unexpected repository response count. No skill content was used.');
  const repositories = [];
  for (let i = 0; i < responses.length; i++) {
    const reply = responses[i];
    const repo = expanded[i].repository;
    if (!reply || reply.statusCode !== 200 || !reply.body || !Array.isArray(reply.body.tree) || reply.body.truncated) throw new Error(`Cannot index the complete pinned tree for ${repo.key}. Check its commit, credential, visibility and GitHub limits.`);
    if (reply.body.tree.length > validated.maxTreeEntries) throw new Error(`Repository ${repo.key} exceeds the documented tree limit. Choose a smaller approved skill repository.`);
    const inRoot = p => repo.roots.some(root => root === '' || p === root || p.startsWith(root + '/'));
    const cleanPath = p => typeof p === 'string' && p.length <= 300 && !/[%?#\\\u0000-\u001f\u007f]/.test(p) && !p.startsWith('/') && !p.endsWith('/') && !p.split('/').some(s => !s || s === '.' || s === '..');
    const tree = reply.body.tree.filter(e => cleanPath(e.path) && inRoot(e.path));
    for (const root of repo.roots) {
      if (root !== '' && !tree.some(e => e.path === root && e.type === 'tree')) throw new Error(`Approved root ${root} does not exist in ${repo.key} at the pinned commit.`);
    }
    const directories = [...new Set([...repo.roots, ...tree.filter(e => e.type === 'tree').map(e => e.path)])];
    const files = tree.filter(e => e.type === 'blob' && ['100644', '100755'].includes(e.mode) && /\.md$/i.test(e.path) && Number.isSafeInteger(e.size) && e.size > 0 && e.size <= validated.maxFileBytes).map(e => ({ path: e.path, size: e.size }));
    if (!files.length || files.length > validated.maxMarkdownFiles) throw new Error(`Repository ${repo.key} must contain between 1 and ${validated.maxMarkdownFiles} regular Markdown files within the size limit and approved roots.`);
    const directoryCounts = Object.fromEntries(directories.map(dir => [dir, tree.filter(e => e.path.slice(0, Math.max(0, e.path.lastIndexOf('/'))) === dir && (e.path.includes('/') || dir === '')).length]));
    const entryPoints = repo.roots.map(root => ({ path: root, entries: tree.filter(e => (e.path.includes('/') ? e.path.slice(0, e.path.lastIndexOf('/')) : '') === root).slice(0, 50).map(e => ({ path: e.path, type: e.type })) }));
    repositories.push({ ...repo, directories, directoryCounts, files, entryPoints });
  }
  return { ...validated, repositories, availableSkills: repositories.map(r => ({ repository: r.key, pinnedCommit: r.commit, approvedRoots: r.roots, entryPoints: r.entryPoints, readableMarkdownFiles: r.files.length })) };
}
const cfg = $('Validate setup and chat').first().json;
const expanded = $('Expand approved repositories').all().map(i => i.json);
return [{json:prepareIndex($input.all().map(i => i.json), expanded, cfg)}];

