={{ (function githubToolUrl(config, repositoryKey, requestedPath, kind) {
  if (typeof repositoryKey !== 'string') throw new Error('Choose a configured repository key.');
  const repo = config.repositories.find(r => r.key === repositoryKey);
  if (!repo) throw new Error('Repository is outside the configured allowlist.');
  if (typeof requestedPath !== 'string' || requestedPath.length > 300 || /[%?#\\\u0000-\u001f\u007f]/.test(requestedPath) || requestedPath.startsWith('/') || requestedPath.endsWith('/') || requestedPath.split('/').some(s => s === '.' || s === '..' || (!s && requestedPath !== ''))) throw new Error('Use a clean repository-relative path without URL syntax or traversal.');
  if (!repo.roots.some(root => root === '' || requestedPath === root || requestedPath.startsWith(root + '/'))) throw new Error('Path is outside the approved repository roots.');
  if (kind === 'directory') {
    if (!repo.directories.includes(requestedPath)) throw new Error('Only directories found in the pinned repository tree may be listed.');
    if (repo.directoryCounts[requestedPath] > config.maxDirectoryEntries) throw new Error('This directory is too large for a bounded tool reply. Choose a smaller approved skill root.');
  } else if (kind === 'markdown') {
    const file = repo.files.find(f => f.path === requestedPath);
    if (!file || file.size > config.maxFileBytes) throw new Error('Only indexed regular Markdown files within the size limit may be read. Symlinks, submodules and oversized files are excluded.');
  } else throw new Error('Unsupported GitHub tool action.');
  const encodedPath = requestedPath.split('/').filter(Boolean).map(encodeURIComponent).join('/');
  return 'https://api.github.com/repos/' + encodeURIComponent(repo.owner) + '/' + encodeURIComponent(repo.repo) + '/contents' + (encodedPath ? '/' + encodedPath : '') + '?ref=' + repo.commit;
})($('Prepare approved skill index').first().json, $fromAI('repositoryKey', 'Exact approved repository key from the library index', 'string'), $fromAI('Path', 'Exact repository-relative directory path. Use an empty string only for an approved repository root', 'string'), 'directory') }}

