function validateAnswer(input) {
  if (!input || typeof input.output !== 'string' || !input.output.trim()) throw new Error('The agent did not produce a text answer. Check its model and tool configuration.');
  const output = input.output.replace(/!\[/g, '[Image omitted: ').replace(/<[^>]*>/g, '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').trim();
  if (output.length > 20000) throw new Error('The agent answer exceeded the 20000-character response limit. Narrow the request.');
  return { output };
}
return [{json:validateAnswer($input.first().json)}];
